import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_positions = inputs["target_positions"].copy()
    position_events = inputs["position_events"].copy()

    # Ensure proper types
    target_positions["account_id"] = target_positions["account_id"].astype("int64")
    target_positions["symbol"] = target_positions["symbol"].astype("str")
    target_positions["qty"] = target_positions["qty"].astype("int64")
    target_positions["price"] = target_positions["price"].astype("float64")
    target_positions["row_version"] = target_positions["row_version"].astype("int64")

    position_events["batch_seq"] = position_events["batch_seq"].astype("int64")
    position_events["account_id"] = position_events["account_id"].astype("int64")
    position_events["symbol"] = position_events["symbol"].astype("str")
    position_events["op"] = position_events["op"].astype("str")
    position_events["qty"] = position_events["qty"].astype("float64")
    position_events["price"] = position_events["price"].astype("float64")
    position_events["row_version"] = position_events["row_version"].astype("int64")

    # Step 1: Deduplicate events by batch_seq (keep first occurrence)
    position_events = position_events.drop_duplicates(subset=["batch_seq"], keep="first").reset_index(drop=True)

    # Step 2: Apply replay guard per key
    # For each key, filter out events with row_version <= current row_version in target
    target_dict = {}
    for _, row in target_positions.iterrows():
        key = (row["account_id"], row["symbol"])
        target_dict[key] = row["row_version"]

    def passes_replay_guard(event_row):
        key = (event_row["account_id"], event_row["symbol"])
        if key in target_dict:
            return event_row["row_version"] > target_dict[key]
        return True

    position_events["passes_guard"] = position_events.apply(passes_replay_guard, axis=1)
    position_events = position_events[position_events["passes_guard"]].drop(columns=["passes_guard"]).reset_index(drop=True)

    # Step 3: Sort events by row_version, then batch_seq for deterministic order
    position_events = position_events.sort_values(by=["row_version", "batch_seq"]).reset_index(drop=True)

    # Step 4: Build state dict from target_positions
    state = {}
    closed_positions_dict = {}

    for _, row in target_positions.iterrows():
        key = (row["account_id"], row["symbol"])
        state[key] = {
            "qty": row["qty"],
            "price": row["price"],
            "row_version": row["row_version"]
        }

    # Step 5: Apply events in order
    for _, event in position_events.iterrows():
        key = (event["account_id"], event["symbol"])
        op = event["op"]
        event_qty = event["qty"]
        event_price = event["price"]
        event_row_version = event["row_version"]

        row_exists = key in state

        if op == "D":
            # Delete: remove the row
            if row_exists:
                del state[key]
                closed_positions_dict[key] = event_row_version
        elif op in ("I", "U"):
            # Check if qty is 0 (closes position)
            is_close = (event_qty == 0) if pd.notna(event_qty) else False

            if is_close:
                # Close: remove if exists
                if row_exists:
                    del state[key]
                    closed_positions_dict[key] = event_row_version
            else:
                # Update or Insert
                if row_exists:
                    # Update existing row
                    state[key]["qty"] = int(event_qty) if pd.notna(event_qty) else state[key]["qty"]
                    # For 'U', keep existing price if event price is NULL
                    if op == "U":
                        if pd.notna(event_price):
                            state[key]["price"] = event_price
                    else:  # 'I'
                        state[key]["price"] = event_price
                    state[key]["row_version"] = event_row_version
                else:
                    # Create new row
                    state[key] = {
                        "qty": int(event_qty) if pd.notna(event_qty) else None,
                        "price": event_price,
                        "row_version": event_row_version
                    }

    # Step 6: Build output DataFrames
    new_positions_rows = []
    for (account_id, symbol), pos_data in state.items():
        new_positions_rows.append({
            "account_id": account_id,
            "symbol": symbol,
            "qty": pos_data["qty"],
            "price": pos_data["price"],
            "row_version": pos_data["row_version"]
        })

    closed_positions_rows = []
    for (account_id, symbol), closed_version in closed_positions_dict.items():
        closed_positions_rows.append({
            "account_id": account_id,
            "symbol": symbol,
            "closed_version": closed_version
        })

    # Create output DataFrames
    if new_positions_rows:
        new_positions = pd.DataFrame(new_positions_rows)
        new_positions = new_positions.astype({
            "account_id": "int64",
            "symbol": "str",
            "qty": "int64",
            "price": "float64",
            "row_version": "int64"
        })
    else:
        new_positions = pd.DataFrame(columns=["account_id", "symbol", "qty", "price", "row_version"])
        new_positions = new_positions.astype({
            "account_id": "int64",
            "symbol": "str",
            "qty": "int64",
            "price": "float64",
            "row_version": "int64"
        })

    if closed_positions_rows:
        closed_positions = pd.DataFrame(closed_positions_rows)
        closed_positions = closed_positions.astype({
            "account_id": "int64",
            "symbol": "str",
            "closed_version": "int64"
        })
    else:
        closed_positions = pd.DataFrame(columns=["account_id", "symbol", "closed_version"])
        closed_positions = closed_positions.astype({
            "account_id": "int64",
            "symbol": "str",
            "closed_version": "int64"
        })

    return {
        "new_positions": new_positions,
        "closed_positions": closed_positions
    }
